# Build a flow once, then render it. Most of the package's pipeline # functions are modular and intended to be composed like this rather # than run in isolation; see the vignettes for fuller treatments. flow <- enroll(n = 1200) |>   phase("Enrollment") |>   exclude("Excluded", n = 150,     reasons = c("Did not meet criteria" = 55,                 "Declined to participate" = 48,                 "Other reasons" = 47)) |>   phase("Allocation") |>   allocate(labels = c("Treatment", "Control"),            n = c(520, 530)) |>   phase("Analysis") |>   endpoint("Final Analysis")  # The "dot" engine returns a Graphviz DOT string and draws nothing, # so it runs anywhere without opening a graphics device. dot <- flowchart(flow, engine = "dot") substr(dot, 1, 50) #> [1] "digraph selecta {
  rankdir=TB;
  splines=ortho;
 "  # The "grid" engine draws to the active graphics device. These calls are # guarded with interactive() so they render in an interactive session but # are skipped during non-interactive documentation builds, where the # diagram cannot be sized to the page and would render incorrectly. if (interactive()) {   flowchart(flow)            # draws to the active device   plot(flow)                 # plot() is a thin wrapper around flowchart()    # Locale-aware counts: a European thousands separator.   enroll(n = 12500) |>     exclude("Excluded", n = 1450) |>     endpoint("Analyzed") |>     flowchart(number_format = "eu") }
